// ---------------------------------------------------------------------------
// GameKitShaders.cs
// Purpose : Checks the kit's shader recipes (Assets/Shaders/Kit/*.shader, generated by tools/shaders/shader_gen.py):
//           Check() reports every recipe's compile errors, Render() draws each into a 64x64 picture for
//           tools/shaders/shader_ref.py compare.
// Usage   : python tools/dev.py check            (runs Check after the C# compile; --no-shaders skips it)
//           python tools/dev.py smoke --shaders  (runs Render with a graphics device, then the compare)
// Notes   : Prints "SHADER_OK <name>" or "SHADER_FAIL <name> <message>" per recipe and
//           "SHADER_CHECK_DONE <recipes> <failed>", then exits 0 or 1 (dev.py reads them from the log).
//           Pseudocode for Render
//             per recipe: its inputs from the "// kit-inputs: main aux" line, loaded linear and point-filtered
//             from data/shaders/inputs/; a linear ARGB32 64x64 RenderTexture; blend One Zero (the shader's output
//             is written as is); Graphics.Blit(main, target, material); ReadPixels -> EncodeToPNG
//           The recipes are unlit passes with no LightMode tag, which the Built-in pipeline and URP both draw
//           (URP as SRPDefaultUnlit): checked with Unity 6000.6 on the Built-in pipeline (D3D11) and with URP 17.6
//           (D3D12), there both through this Blit and through a URP camera in play mode. HDRP is not checked.
// Authored: Written with Claude (Opus 5.5, claude-opus-5-5)
// ---------------------------------------------------------------------------
using System;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;
using UnityEditor;
using UnityEngine;

public static class GameKitShaders
{
    // ---- Tunables ------------------------------------------------------------
    public const string ShaderFolder = "Assets/Shaders/Kit";
    const string InputFolder = "data/shaders/inputs";    // relative to the project folder (above Assets/)
    const int Size = 64;                                   // the check canvas (tools/shaders/recipes.json)
    const string OutArg = "-shaderOut";                    // Render's output folder on the command line

    static string[] ShaderPaths() =>
        Directory.Exists(ShaderFolder)
            ? Directory.GetFiles(ShaderFolder, "*.shader").Select(p => p.Replace('\\', '/')).OrderBy(p => p).ToArray()
            : new string[0];

    /// Compile every recipe and report its errors. Exit 1 when one fails.
    public static void Check()
    {
        AssetDatabase.Refresh();
        var paths = ShaderPaths();
        int failed = 0;
        foreach (var path in paths)
        {
            var name = Path.GetFileNameWithoutExtension(path);
            var shader = AssetDatabase.LoadAssetAtPath<Shader>(path);
            string why = null;
            if (shader == null)
                why = "not imported as a shader";
            else if (ShaderUtil.ShaderHasError(shader))
                why = string.Join(" | ", ShaderUtil.GetShaderMessages(shader)
                    .Where(m => m.severity == UnityEditor.Rendering.ShaderCompilerMessageSeverity.Error)
                    .Select(m => $"line {m.line}: {m.message}"));
            if (why == null)
            {
                Debug.Log($"SHADER_OK {name}");
            }
            else
            {
                failed++;
                Debug.Log($"SHADER_FAIL {name} {why}");
            }
        }
        Done(paths.Length, failed);
    }

    /// Draw every recipe into <-shaderOut>/<name>.png. Needs a graphics device (no -nographics).
    public static void Render()
    {
        AssetDatabase.Refresh();
        var args = Environment.GetCommandLineArgs();
        int at = Array.IndexOf(args, OutArg);
        if (at < 0 || at + 1 >= args.Length)
        {
            Debug.LogError($"[ERROR] GameKitShaders.Render needs {OutArg} <folder>");
            EditorApplication.Exit(2);
            return;
        }
        var outDir = args[at + 1];
        Directory.CreateDirectory(outDir);
        if (SystemInfo.graphicsDeviceType == UnityEngine.Rendering.GraphicsDeviceType.Null)
        {
            Debug.LogError("[ERROR] no graphics device (-nographics): the shader check cannot draw");
            EditorApplication.Exit(2);
            return;
        }
        var paths = ShaderPaths();
        int failed = 0;
        foreach (var path in paths)
        {
            var name = Path.GetFileNameWithoutExtension(path);
            try
            {
                var png = Draw(path);
                File.WriteAllBytes(Path.Combine(outDir, name + ".png"), png);
                Debug.Log($"SHADER_OK {name}");
            }
            catch (Exception e)
            {
                failed++;
                Debug.Log($"SHADER_FAIL {name} {e.Message}");
            }
        }
        Done(paths.Length, failed);
    }

    static byte[] Draw(string path)
    {
        var shader = AssetDatabase.LoadAssetAtPath<Shader>(path);
        if (shader == null || ShaderUtil.ShaderHasError(shader))
            throw new InvalidOperationException("the shader does not compile (python tools/dev.py check)");
        var inputs = Regex.Match(File.ReadAllText(path), @"^// kit-inputs: (\w+) (\S+)", RegexOptions.Multiline);
        if (!inputs.Success)
            throw new InvalidOperationException("no // kit-inputs: line (regenerate with tools/shaders/shader_gen.py)");
        // Everything made here is destroyed again (an editor session can run the check many times)
        var made = new System.Collections.Generic.List<UnityEngine.Object>();
        var previous = RenderTexture.active;
        RenderTexture target = null;
        try
        {
            var material = new Material(shader);
            made.Add(material);
            material.SetFloat("_SrcBlend", (float)UnityEngine.Rendering.BlendMode.One);
            material.SetFloat("_DstBlend", (float)UnityEngine.Rendering.BlendMode.Zero);
            var main = Input(inputs.Groups[1].Value);
            made.Add(main);
            if (inputs.Groups[2].Value != "-")
            {
                var aux = Input(inputs.Groups[2].Value);
                made.Add(aux);
                material.SetTexture("_AuxTex", aux);
            }
            target = new RenderTexture(Size, Size, 0, RenderTextureFormat.ARGB32, RenderTextureReadWrite.Linear);
            Graphics.Blit(main, target, material);
            RenderTexture.active = target;
            var read = new Texture2D(Size, Size, TextureFormat.RGBA32, false, true);
            made.Add(read);
            read.ReadPixels(new Rect(0, 0, Size, Size), 0, 0);
            read.Apply();
            return read.EncodeToPNG();
        }
        finally
        {
            RenderTexture.active = previous;
            if (target != null)
            {
                target.Release();
                UnityEngine.Object.DestroyImmediate(target);
            }
            foreach (var o in made)
                UnityEngine.Object.DestroyImmediate(o);
        }
    }

    /// An input picture, linear and point-filtered ("sphere" is the sphere's normal map).
    static Texture2D Input(string name)
    {
        var file = Path.Combine(InputFolder, (name == "sphere" ? "sphere_normal" : name) + ".png");
        if (!File.Exists(file))
            throw new FileNotFoundException($"no input picture {file}");
        var tex = new Texture2D(2, 2, TextureFormat.RGBA32, false, true);
        if (!tex.LoadImage(File.ReadAllBytes(file)))
            throw new InvalidDataException($"{file} is not a PNG Unity can read");
        tex.filterMode = FilterMode.Point;
        tex.wrapMode = TextureWrapMode.Clamp;
        return tex;
    }

    static void Done(int count, int failed)
    {
        if (count == 0)
        {
            // No recipes found is not a pass: the folder is missing or the editor runs in another project
            Debug.Log($"SHADER_FAIL * no shader recipes in {ShaderFolder} (python tools/shaders/shader_gen.py)");
            failed = 1;
        }
        Debug.Log($"SHADER_CHECK_DONE {count} {failed}");
        if (Application.isBatchMode)
            EditorApplication.Exit(failed > 0 ? 1 : 0);
    }
}
